mapper.update:
UPDATE product
name = #{name}, category_id = #{categoryId}, specification = #{specification}, unit_id = #{unitId}, safety_stock = #{safetyStock}, manufacturer = #{manufacturer}, batch_number = #{batchNumber}, production_date = #{productionDate}, expiry_date = #{expiryDate}, purchase_price = #{purchasePrice}, selling_price = #{sellingPrice}, description = #{description}, status = #{status},
WHERE id = #{id}

mapper.select:
SELECT p.*, c.name AS category_name, u.name AS unit_name, IFNULL(i.current_stock, 0) AS current_stock FROM product p LEFT JOIN product_category c ON p.category_id = c.id LEFT JOIN unit u ON p.unit_id = u.id LEFT JOIN inventory i ON p.id = i.product_id
AND p.name LIKE CONCAT('%', #{name}, '%')
AND p.category_id = #{categoryId}
AND p.status = #{status}
AND p.manufacturer LIKE CONCAT('%', #{manufacturer}, '%')
AND p.safety_stock > 0 AND IFNULL(i.current_stock, 0) < p.safety_stock
ORDER BY p.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(DISTINCT p.id) FROM product p LEFT JOIN inventory i ON p.id = i.product_id
AND p.name LIKE CONCAT('%', #{name}, '%')
AND p.category_id = #{categoryId}
AND p.status = #{status}
AND p.manufacturer LIKE CONCAT('%', #{manufacturer}, '%')
AND p.safety_stock > 0 AND IFNULL(i.current_stock, 0) < p.safety_stock
